(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.33)*12;
  const w2x = Math.sin((x+y)*0.012+t*0.45)*8 + Math.cos((x-y)*0.009-t*0.35)*6;
  const w2y = Math.cos((x-y)*0.012-t*0.4)*8 + Math.sin((x+y)*0.01+t*0.5)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*55, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+2)*95, 200+Math.sin(t*0.75+4)*65, 0.065, 2.4, 1.12],
    [200+Math.sin(t*0.25+1)*130, 220+Math.cos(t*0.45+3)*70, 0.095, 1.8, 0.92],
    [300+Math.cos(t*0.7+5)*85, 100+Math.sin(t*0.5+2)*80, 0.075, 2.2, 1.08]
  ];
  let aS = 0, iS = 0, cross = 0;
  for (let i = 0; i < src.length; i++) {
    const [sX, sY, f, sp, w] = src[i];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const a = Math.sin(d*f - t*sp);
    const inh = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += a * w;
    iS += inh * w;
    for (let j = i+1; j < src.length; j++) {
      const [sX2, sY2, f2, sp2] = src[j];
      const d2 = Math.sqrt((sx-sX2)**2 + (sy-sY2)**2);
      cross += Math.sin(d*f + d2*f2 - t*(sp+sp2)*0.5) * w * src[j][4] * 0.04;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
