  const vortex = Math.sin(ang*2+dist*0.03-t*1.8)*Math.exp(-dist*0.004)*0.3;
  const react = act - inh*0.7 + bg*0.3 + spiral + cross + vortex;
  const lap = Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5
    + Math.sin(sx*0.22-sy*0.18+t*1.4)*0.3;
  const cell = Math.tanh(lap*1.5)*0.3;
  const reaction = Math.tanh(react*2.2);
  const noise = (Math.sin(sx*0.31+t*2.2)*Math.sin(sy*0.37-t*1.7)
    + Math.sin(sx*0.17+sy*0.23+t*3.1)*0.5)*0.08;
  const blend = reaction*0.65 + cell*0.25 + noise;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [
    [6,12,52],[12,42,88],[18,85,125],[25,138,138],
    [65,175,145],[170,200,95],[220,185,60],[225,135,55],
    [195,75,65],[145,40,70],[85,22,65],[40,14,55],[6,12,52]
