    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*pulse*edge + glow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*pulse*edge + glow*15)|0)
  ];
}
